import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import * as c from '../src/index.js';
const raw=readFileSync(new URL('../integration/fixtures/curriculum-v5-330.json',import.meta.url),'utf8');
const data=JSON.parse(raw);const copy=value=>structuredClone(value);
const digest=value=>createHash('sha256').update(value).digest('hex');
const report=c.inspectCurriculum(data);
const unit=report.quickReviews[0].unitId;
const doneFor=id=>data.lessons.filter(lesson=>lesson.unit_id===id).map(lesson=>lesson.id);
const build=(id=unit,options={})=>c.buildCurriculumQuickReview(data,id,{completedLessonIds:doneFor(id),...options});
const session=(id=unit,options={})=>c.createChapterReviewSession(build(id,options).plan,{sessionId:`adapter-${id}`,profileId:'demo-profile'});
const begin=s=>c.transitionChapterReview(s,{type:'begin'});
const current=s=>s.queue[s.cursor];
const next=s=>c.transitionChapterReview(s,{type:'next'});
const answer=(s,correct=true)=>c.transitionChapterReview(s,{type:'answer',questionId:current(s).id,response:correct?current(s).correctOptionId:current(s).options.find(option=>option.id!==current(s).correctOptionId).id,at:'2026-11-08T02:00:00.000Z',timeZone:'Asia/Ho_Chi_Minh',durationMs:2500});
const challengeList=data.lessons.flatMap(lesson=>lesson.activities.filter(activity=>activity.type==='interactive_challenge'));

test('real v5 data structurally validates with exact expected counts',()=>{assert.equal(report.lessons,330);assert.equal(report.units,54);assert.equal(report.vocabularyCards,140);assert.equal(report.languageTargets,160);assert.equal(report.quickReviews.length,10);assert.equal(report.quickReviews.reduce((s,r)=>s+r.questionCount,0),30);assert.equal(report.interactiveChallenges.length,10);});
test('adapter preserves every unit, lesson and target identifier',()=>{const result=c.adaptCurriculumCatalog(data);assert.deepEqual(result.catalog.cards.map(card=>card.id),[...data.vocabulary,...data.language_targets].map(card=>card.id));assert.deepEqual(result.catalog.lessons.map(lesson=>lesson.id),data.lessons.map(lesson=>lesson.id));assert.deepEqual(result.chapters.map(chapter=>chapter.id),data.units.map(unit=>unit.id));assert.equal(result.catalog.cards.length,300);});
test('adapter never modifies its real source dataset',()=>{const before=digest(JSON.stringify(data));c.adaptCurriculumCatalog(data);build();assert.equal(digest(JSON.stringify(data)),before);});
test('full data retains all 732 choice activity records while validating their keys',()=>{const count=data.lessons.flatMap(lesson=>lesson.activities).filter(activity=>activity.type==='choice').length;assert.equal(count,732);assert.ok(report.activityTypes.includes('speaking_manual'));});
test('all ten authored reviews run through the shared session reducer',()=>{for(const review of report.quickReviews){let state=begin(session(review.unitId));for(let i=0;i<3;i++)state=next(answer(state));assert.equal(state.status,'completed');assert.equal(state.result.firstPassCorrect,3);assert.equal(state.result.durationMs,7500);assert.equal(state.events.length,0);const outcomes=c.curriculumQuestionOutcomes(state);assert.equal(outcomes.length,3);assert.equal(outcomes[0].unitId,review.unitId);assert.equal(outcomes[0].activityId,review.activityId);assert.deepEqual(outcomes.map(outcome=>outcome.questionId),state.plan.source.questionIds);}});
test('raw quick-review question IDs and option IDs are preserved, never replaced with q1 IDs',()=>{const result=build();const original=data.lessons.find(lesson=>lesson.id===result.plan.source.lessonId).activities.find(a=>a.id===result.plan.source.activityId);assert.deepEqual(result.plan.questions.map(q=>q.id),original.questions.map(q=>q.id));assert.deepEqual(result.plan.questions[0].options.map(o=>o.id),original.questions[0].options.map(o=>o.id));});
test('question-only assessment does not pretend a broad review proves a specific word was learned',()=>{let state=begin(session());state=answer(state);assert.equal(state.events.length,0);assert.equal(state.attempts[0].cardId,null);assert.equal(state.result,null);assert.equal(c.curriculumQuestionOutcomes(state)[0].assessed,true);});
test('failed chapter question creates retry and question-level needs-practice record',()=>{let state=next(answer(begin(session()),false));state=next(answer(state));state=next(answer(state));state=next(answer(state,false));assert.equal(state.result.firstPassCorrect,2);assert.equal(state.result.totalAttempts,4);assert.equal(state.result.practiceAgainCardIds.length,0);assert.deepEqual(state.result.practiceAgainQuestionIds,[state.plan.questions[0].id]);assert.equal(state.events.length,0);});
test('adapter exposes three authored questions, not a fabricated five-round review',()=>{const plan=build().plan;assert.equal(plan.questions.length,3);assert.equal(plan.completeFiveStepPattern,false);assert.equal(plan.timed,false);assert.equal(plan.source.timerRequired,false);assert.equal(plan.source.durationHintSeconds,90);});
test('units without authored reviews are reported as unavailable without invented questions',()=>{const r=c.buildCurriculumQuickReview(data,'animals');assert.equal(r.available,false);assert.equal(r.reason,'no_authored_quick_review');assert.equal(r.plan,null);});
test('review lesson must have been introduced before adapting its questions',()=>{const r=c.buildCurriculumQuickReview(data,unit);assert.equal(r.available,true);assert.equal(r.reason,'review_lesson_not_introduced');assert.equal(r.plan,null);});
test('introduced review can run in practice mode without falsely completing earlier lessons',()=>{const sourceLesson=report.quickReviews[0].lessonId;const r=c.buildCurriculumQuickReview(data,unit,{introducedLessonIds:[sourceLesson]});assert.equal(r.plan.readiness.ready,false);assert.throws(()=>c.createChapterReviewSession(r.plan,{sessionId:'pending',profileId:'p'}));assert.equal(c.createChapterReviewSession(r.plan,{sessionId:'pending',profileId:'p',mode:'practice'}).mode,'practice');});
test('younger and shortened reviews route to adult observation',()=>{for(const options of [{ageBand:'ages_5_7'},{shortened:true}]){let state=begin(session(unit,options));assert.ok(state.plan.questions.every(question=>question.assessment==='adult_observation'));assert.throws(()=>c.transitionChapterReview(state,{type:'answer',questionId:current(state).id,response:'0',at:'2026-11-08T02:00:00.000Z',timeZone:'Asia/Ho_Chi_Minh',durationMs:1000}),/adult observation/);state=c.transitionChapterReview(state,{type:'observe',questionId:current(state).id,observation:'supported'});assert.equal(state.events.length,0);assert.equal(c.curriculumQuestionOutcomes(state)[0].observation,'supported');}});
test('snapshot restores same source question and does not duplicate a round',()=>{let state=next(answer(begin(session()),false));state=c.transitionChapterReview(state,{type:'hint',questionId:current(state).id});const restored=c.restoreCurriculumReviewSnapshot(c.exportChapterReviewSnapshot(state),data,state.profileId);assert.deepEqual(restored,state);assert.equal(c.curriculumQuestionOutcomes(restored).length,1);assert.equal(restored.queue.length,4);});
test('changing curriculum version or content refuses silent snapshot migration',()=>{const state=begin(session());const changed=copy(data);changed.content_version='new-version';assert.throws(()=>c.restoreCurriculumReviewSnapshot(c.exportChapterReviewSnapshot(state),changed,state.profileId),/plan changed/);});
test('wrong profile and unsupported adapter snapshots are rejected',()=>{const state=begin(session());const serialized=c.exportChapterReviewSnapshot(state);assert.throws(()=>c.restoreCurriculumReviewSnapshot(serialized,data,'other'));const saved=JSON.parse(serialized);saved.recipe.adapter='unknown';assert.throws(()=>c.restoreCurriculumReviewSnapshot(JSON.stringify(saved),data,state.profileId));});
test('all adapted focus cards and view models retain no recorded audio',()=>{const plan=build().plan;assert.equal(plan.source.audio,null);assert.ok(plan.focusCards.every(card=>card.audioId===null));const view=c.chapterQuestionView(begin(session()));assert.equal('correctOptionId'in view,false);});
test('all ten full interactive answer keys grade correctly',()=>{for(const challenge of challengeList){assert.equal(c.gradeInteractiveChallenge(challenge,challenge.answer).correct,true);const view=c.interactiveChallengeView(challenge);assert.equal('answer'in view,false);assert.equal(view.requiresDrag,false);assert.equal(view.requiresMicrophone,false);assert.equal(view.audio,null);}});
test('all ten shortened challenges remain observed, never exact scored',()=>{for(const challenge of challengeList){const r=c.gradeInteractiveChallenge(challenge,null,{shortened:true});assert.equal(r.autoGraded,false);assert.equal(r.correct,null);assert.equal(c.interactiveChallengeView(challenge,{ageBand:'ages_5_7'}).assessment,'adult_observation');}});
test('selected-ID challenge ignores order but detects a different set',()=>{const challenge=challengeList.find(c=>c.answer.selected_ids?.length>1);assert.equal(c.gradeInteractiveChallenge(challenge,{selected_ids:[...challenge.answer.selected_ids].reverse()}).correct,true);assert.equal(c.gradeInteractiveChallenge(challenge,{selected_ids:[]}).correct,false);});
test('ordered challenge requires complete correct sequence',()=>{const challenge=challengeList.find(c=>c.answer.ordered_ids);assert.equal(c.gradeInteractiveChallenge(challenge,{ordered_ids:[...challenge.answer.ordered_ids].reverse()}).correct,false);assert.throws(()=>c.gradeInteractiveChallenge(challenge,{ordered_ids:challenge.answer.ordered_ids.slice(1)}));});
test('pair challenge accepts reordered equivalent connections but rejects wrong pairing',()=>{const challenge=challengeList.find(c=>c.answer.pairs);assert.equal(c.gradeInteractiveChallenge(challenge,{pairs:challenge.answer.pairs.map(pair=>[...pair].reverse()).reverse()}).correct,true);const [[a,b],[d,e]]=challenge.answer.pairs;assert.equal(c.gradeInteractiveChallenge(challenge,{pairs:[[a,e],[d,b]]}).correct,false);});
test('group challenge compares named groups and does not care about order within group',()=>{const challenge=challengeList.find(c=>c.answer.groups);const swapped=Object.fromEntries(Object.entries(challenge.answer.groups).map(([k,v])=>[k,[...v].reverse()]));assert.equal(c.gradeInteractiveChallenge(challenge,{groups:swapped}).correct,true);const keys=Object.keys(swapped);[swapped[keys[0]][0],swapped[keys[1]][0]]=[swapped[keys[1]][0],swapped[keys[0]][0]];assert.equal(c.gradeInteractiveChallenge(challenge,{groups:swapped}).correct,false);});
test('structured responses reject duplicate/unknown IDs and multiple answer modes',()=>{const challenge=challengeList.find(c=>c.answer.selected_ids);assert.throws(()=>c.gradeInteractiveChallenge(challenge,{selected_ids:['missing']}));assert.throws(()=>c.gradeInteractiveChallenge(challenge,{selected_ids:[challenge.items[0].id,challenge.items[0].id]}));assert.throws(()=>c.gradeInteractiveChallenge(challenge,{selected_ids:[],ordered_ids:[]}));});
test('corrupt source references fail before creating a catalog',()=>{const changed=copy(data);changed.lessons[0].focus_vocabulary_ids.push('missing');assert.throws(()=>c.adaptCurriculumCatalog(changed),/unknown/);});
test('corrupt quick-review answer key fails validation',()=>{const changed=copy(data);const review=changed.lessons.flatMap(l=>l.activities).find(a=>a.type==='quick_review');review.questions[0].answer_option_id='missing';assert.throws(()=>c.inspectCurriculum(changed),/missing option/);});
test('curriculum revisions must be explicitly supported',()=>{const changed=copy(data);changed.schema_version='1.5.0';assert.throws(()=>c.inspectCurriculum(changed),/schemas 1.4.0, 1.4.1, 1.4.2 only/);});
test('unsupported units, age bands and false prior-lesson IDs fail clearly',()=>{assert.throws(()=>build('not-a-unit'));assert.throws(()=>build(unit,{ageBand:'adult'}));assert.throws(()=>build(unit,{completedLessonIds:['missing']}));});
test('question-only rounds still reject backwards timestamps without card events',()=>{let state=next(answer(begin(session())));assert.equal(state.events.length,0);assert.throws(()=>c.transitionChapterReview(state,{type:'answer',questionId:current(state).id,response:current(state).correctOptionId,at:'2026-11-08T01:00:00.000Z',timeZone:'Asia/Ho_Chi_Minh',durationMs:200}),/nondecreasing/);});
test('skipped imported question is preserved by source ID in deferred outcomes',()=>{let state=begin(session());const qid=current(state).id;state=c.transitionChapterReview(state,{type:'skip',questionId:qid});assert.deepEqual(c.summarizeChapterReview(state).deferredQuestionIds,[qid]);assert.equal(c.curriculumQuestionOutcomes(state)[0].skipped,true);});
test('story-dependent quick reviews fail clearly until story delivery is implemented',()=>{const changed=copy(data);const activity=changed.lessons.find(lesson=>lesson.id===report.quickReviews[0].lessonId).activities.find(a=>a.type==='quick_review');activity.questions[0].text_variant_required='text_en';assert.throws(()=>c.buildCurriculumQuickReview(changed,unit,{completedLessonIds:doneFor(unit)}),/story delivery/);});
